+        uint32_t promotedLevel = m_levels[i];
         m_levels[i] = promotedLevel - 1;
         i++;
         // Now promote all the children of the promoted message.
@@ -1350,7 +1350,7 @@ nsresult nsMsgSearchDBView::ListIdsInThread(
